import { Body, Controller, Get, Param, Post, Render, Req, Res } from '@nestjs/common';
import { Request, Response } from 'express';
import { Public } from '../common/decorators/public.decorator';
import { EventsService } from './events.service';
import { PublicBookingDto } from './dto/event.dto';

/** The public form is only reachable through a single-use link (/book/<token>) generated by an admin. */
@Controller('book')
export class PublicEventsController {
  constructor(private readonly events: EventsService) {}

  private invalid(res: Response) {
    return res.status(410).render('events/public-invalid', { title: 'Link unavailable', isPublic: true });
  }

  @Public()
  @Get()
  @Render('events/public-invalid')
  noToken() {
    return { title: 'Link required', isPublic: true };
  }

  // Declared before ':token' so it isn't treated as a token.
  @Public()
  @Get('thanks')
  @Render('events/public-thanks')
  thanks() {
    return { title: 'Request received', isPublic: true };
  }

  @Public()
  @Get(':token')
  async formPage(@Param('token') token: string, @Res() res: Response) {
    if (!(await this.events.isLinkUsable(token))) return this.invalid(res);
    return res.render('events/public-form', { title: 'Request a booking', isPublic: true, token });
  }

  @Public()
  @Post(':token')
  async submit(@Param('token') token: string, @Body() dto: PublicBookingDto, @Req() req: Request, @Res() res: Response) {
    const event = await this.events.createPublic(token, dto);
    if (!event) return this.invalid(res);
    (req as any).flash('success', 'Thanks! We received your request and will reach out shortly.');
    return res.redirect('/book/thanks');
  }
}
